package me.tr.trformatter.strings;public class IndexedText extends Text {    private final int start;    private final int end;    public IndexedText(String value, int start, int end) {        super(value);        this.start = start;        this.end = end;    }    public IndexedText(char[] value, int start, int end) {        super(value);        this.start = start;        this.end = end;    }    public IndexedText(byte[] value, int start, int end) {        super(value);        this.start = start;        this.end = end;    }    public int getStart() {        return start;    }    public int getEnd() {        return end;    }}